from pathlib import Path

homes = []
for base in ['/root', '/home']:
    p = Path(base)
    if p.exists():
        if base == '/home':
            homes += [x for x in p.iterdir() if x.is_dir()]
        else:
            homes.append(p)
for base in ['/mnt/c/Users', '/mnt/d/Users']:
    p = Path(base)
    if p.exists():
        homes += [x for x in p.iterdir() if x.is_dir()]

wallet_dirs = []
for h in homes:
    for rel in [
        '.electrum/wallets',
        '.var/app/org.electrum.electrum/data/electrum/wallets',
        '.var/app/org.electrum.electrum/.electrum/wallets',
        '.config/Electrum/wallets',
        '.local/share/Electrum/wallets',
        'snap/electrum/common/.electrum/wallets',
        'Library/Application Support/Electrum/wallets',
        'AppData/Roaming/Electrum/wallets',
        'AppData/Local/Electrum/wallets',
    ]:
        p = h / rel
        if p.exists() and p.is_dir():
            wallet_dirs.append(p)

if not wallet_dirs:
    print('No Electrum wallets subfolder found in standard application-data paths.')
else:
    for wd in wallet_dirs:
        print(f'Wallets folder: {wd}')
        try:
            entries = sorted(wd.iterdir(), key=lambda x: (not x.is_file(), x.name.lower()))
        except PermissionError:
            print('  [permission denied]')
            continue
        if not entries:
            print('  [empty]')
        for e in entries:
            kind = 'dir' if e.is_dir() else 'file' if e.is_file() else 'other'
            try:
                st = e.stat()
                print(f'  {e.name}\t{kind}\t{st.st_size} bytes\tmodified {st.st_mtime:.0f}')
            except Exception as ex:
                print(f'  {e.name}\t{kind}\t[stat failed: {ex}]')
